def wrap_nidd_output(_counters_info):  # noqa: C901
    resulting_struct = {}

    def construct_nidd(path):
        return "/".join(path)

    def find_samples(nidd_tree_node, path=None):  # noqa: C901
        if not path:
            path = []

        found_samples = None

        counters = {}
        for k, v in nidd_tree_node.items():
            if isinstance(v, dict):
                # Key is either part of nidd or measurement or counter id
                next_path = path + [k]

                samples_from_leaves = find_samples(nidd_tree_node[k], next_path)

                if samples_from_leaves:
                    counters.update({k: samples_from_leaves})

            else:
                # Found samples in this node!
                # Key is a sample, we gather all of them and return them upwards
                if not found_samples:
                    found_samples = {}
                found_samples.update({k: v})

        if found_samples:
            return found_samples
        elif samples_from_leaves:
            measurement_name = path[-1]
            nidd_path = construct_nidd(path[:-1])

            nidd = resulting_struct.get(nidd_path)
            if nidd:
                measurement = nidd.get(measurement_name)
                if not measurement:
                    measurement = {measurement_name: counters}
                nidd.update(measurement)
            else:
                nidd = {}
                nidd.update({measurement_name: counters})

            resulting_struct.update({nidd_path: nidd})

    try:
        find_samples(_counters_info["TRS"])
    except KeyError:
        pass
    try:
        find_samples(_counters_info["BTS"])
    except KeyError:
        pass

    return resulting_struct
